    72→/* Convert FreeLang type to C type string */
    73→const char *fl_type_to_c_string(FlType *ty) {
    74→    if (!ty) return "void";
    75→
    76→    switch (ty->kind) {
    77→        case FL_TYPE_VOID:
    78→            return "void";
    79→        case FL_TYPE_BOOL:
    80→            return "int";  /* C bool via 0/1 */
    81→        case FL_TYPE_I32:
    82→            return "int";
    83→        case FL_TYPE_I64:
    84→            return "long";
    85→        case FL_TYPE_F32:
    86→            return "float";
    87→        case FL_TYPE_F64:
    88→            return "double";
    89→        case FL_TYPE_STRING:
    90→            return "char*";
    91→        case FL_TYPE_POINTER: {
    92→            static char buf[256];
    93→            const char *pointee_str = fl_type_to_c_string(ty->ptr.pointee_type);
    94→            snprintf(buf, sizeof(buf), "%s*", pointee_str);
    95→            return buf;
    96→        }
    97→        case FL_TYPE_ARRAY: {
    98→            static char buf[256];
    99→            const char *elem_str = fl_type_to_c_string(ty->element_type);
   100→            if (ty->length < 0) {
   101→                snprintf(buf, sizeof(buf), "%s[]", elem_str);
   102→            } else {
   103→                snprintf(buf, sizeof(buf), "%s[%d]", elem_str, ty->length);
   104→            }
   105→            return buf;
   106→        }
   107→        case FL_TYPE_STRUCT:
   108→            return ty->st.name;
   109→        case FL_TYPE_UNKNOWN:
   110→        default:
   111→            return "???";
   112→    }
   113→}
