   115→/* Type size in bytes (simplified) */
   116→int fl_type_size(FlType *ty) {
   117→    if (!ty) return 0;
   118→
   119→    switch (ty->kind) {
   120→        case FL_TYPE_VOID:
   121→            return 0;
   122→        case FL_TYPE_BOOL:
   123→        case FL_TYPE_I32:
   124→            return 4;
   125→        case FL_TYPE_I64:
   126→            return 8;
   127→        case FL_TYPE_F32:
   128→            return 4;
   129→        case FL_TYPE_F64:
   130→            return 8;
   131→        case FL_TYPE_STRING:
   132→        case FL_TYPE_POINTER:
   133→            return 8;  /* 64-bit pointer */
   134→        case FL_TYPE_ARRAY:
   135→            return fl_type_size(ty->element_type) * ty->length;
   136→        case FL_TYPE_STRUCT:
   137→            return 0;  /* Unknown struct size */
   138→        case FL_TYPE_UNKNOWN:
   139→        default:
   140→            return 0;
   141→    }
   142→}
   143→
   144→/* Type equality */
   145→bool fl_type_equals(FlType *a, FlType *b) {
   146→    if (!a || !b) return a == b;
   147→    if (a->kind != b->kind) return false;
   148→
   149→    switch (a->kind) {
   150→        case FL_TYPE_POINTER:
   151→            return fl_type_equals(a->ptr.pointee_type, b->ptr.pointee_type);
   152→        case FL_TYPE_ARRAY:
   153→            return fl_type_equals(a->element_type, b->element_type) &&
   154→                   a->length == b->length;
   155→        case FL_TYPE_STRUCT:
   156→            return strcmp(a->st.name, b->st.name) == 0;
   157→        default:
   158→            return a->kind == b->kind;
   159→    }
   160→}
   161→
   162→/* Free type recursively */
   163→void fl_type_free(FlType *ty) {
   164→    if (!ty) return;
   165→
   166→    switch (ty->kind) {
   167→        case FL_TYPE_POINTER:
   168→            fl_type_free(ty->ptr.pointee_type);
   169→            break;
   170→        case FL_TYPE_ARRAY:
   171→            fl_type_free(ty->element_type);
   172→            break;
   173→        case FL_TYPE_STRUCT:
   174→            free((void *)ty->st.name);
   175→            break;
   176→        default:
   177→            break;
   178→    }
   179→
   180→    free(ty);
   181→}
