   237→/* ===== Parser ===== */
   238→
   239→Parser *parser_new(const char *input) {
   240→    Parser *p = malloc(sizeof(Parser));
   241→    p->lexer = lexer_new(input);
   242→    p->current = lexer_next(p->lexer);
   243→    p->peek = lexer_next(p->lexer);
   244→    return p;
   245→}
   246→
   247→void parser_free(Parser *p) {
   248→    if (p) {
   249→        lexer_free(p->lexer);
   250→        free(p);
   251→    }
   252→}
   253→
   254→static void parser_advance(Parser *p) {
   255→    p->current = p->peek;
   256→    p->peek = lexer_next(p->lexer);
   257→}
   258→
   259→static int parser_match(Parser *p, TokenKind kind) {
   260→    return p->current.kind == kind;
   261→}
   262→
   263→static int parser_accept(Parser *p, TokenKind kind) {
   264→    if (parser_match(p, kind)) {
   265→        parser_advance(p);
   266→        return 1;
   267→    }
   268→    return 0;
   269→}
