   282→/* Parse primary expression: literal, variable, (expr) */
   283→static Expr *parse_primary(Parser *p) {
   284→    if (parser_match(p, TOK_INT)) {
   285→        Expr *e = expr_literal_int(p->current.int_value);
   286→        parser_advance(p);
   287→        return e;
   288→    } else if (parser_match(p, TOK_FLOAT)) {
   289→        Expr *e = expr_literal_float(p->current.float_value);
   290→        parser_advance(p);
   291→        return e;
   292→    } else if (parser_match(p, TOK_STRING)) {
   293→        /* Copy string without quotes */
   294→        char str[256];
   295→        strncpy(str, p->current.text, p->current.length);
   296→        str[p->current.length] = '\0';
   297→        Expr *e = expr_literal_string(str);
   298→        parser_advance(p);
   299→        return e;
   300→    } else if (parser_match(p, TOK_IDENT)) {
   301→        char ident[256];
   302→        strncpy(ident, p->current.text, p->current.length);
   303→        ident[p->current.length] = '\0';
   304→        parser_advance(p);
   305→
   306→        Expr *e = expr_var(ident);
   307→        return parse_postfix(p, e);
   308→    } else if (parser_accept(p, TOK_LPAREN)) {
   309→        Expr *e = parse_expression(p);
   310→        parser_accept(p, TOK_RPAREN);
   311→        return e;
   312→    }
   313→
   314→    return expr_literal_int(0); /* error */
   315→}
