   317→static Expr *parse_postfix(Parser *p, Expr *e) {
   318→    /* Handle function calls: name(...) */
   319→    if (parser_match(p, TOK_LPAREN)) {
   320→        /* Get function name from expr */
   321→        if (e->kind != EXPR_VAR) {
   322→            return e;  /* not a function call */
   323→        }
   324→
   325→        const char *func_name = e->var.name;
   326→        parser_advance(p);  /* skip ( */
   327→
   328→        /* Parse arguments */
   329→        Expr **args = malloc(sizeof(Expr *) * 32);
   330→        int arg_count = 0;
   331→
   332→        while (!parser_match(p, TOK_RPAREN) && !parser_match(p, TOK_EOF)) {
   333→            args[arg_count++] = parse_expression(p);
   334→            if (parser_match(p, TOK_COMMA)) {
   335→                parser_advance(p);
   336→            }
   337→        }
   338→
   339→        parser_accept(p, TOK_RPAREN);
   340→
   341→        /* Free the original VAR expr */
   342→        free(e->var.name);
   343→        free(e);
   344→
   345→        /* Return CALL expr */
   346→        return expr_call(func_name, args, arg_count);
   347→    }
   348→
   349→    /* TODO: array indexing, member access */
   350→    return e;
   351→}
