   353→static Expr *parse_unary(Parser *p) {
   354→    if (parser_accept(p, TOK_NOT)) {
   355→        Expr *operand = parse_unary(p);
   356→        return expr_unary(operand, "!");
   357→    } else if (parser_accept(p, TOK_MINUS)) {
   358→        Expr *operand = parse_unary(p);
   359→        return expr_unary(operand, "-");
   360→    }
   361→
   362→    return parse_primary(p);
   363→}
   364→
   365→static Expr *parse_multiplicative(Parser *p) {
   366→    Expr *left = parse_unary(p);
   367→
   368→    while (parser_match(p, TOK_STAR) || parser_match(p, TOK_SLASH)) {
   369→        const char *op = parser_match(p, TOK_STAR) ? "*" : "/";
   370→        parser_advance(p);
   371→        Expr *right = parse_unary(p);
   372→        left = expr_binary(left, right, op);
   373→    }
   374→
   375→    return left;
   376→}
   377→
   378→static Expr *parse_additive(Parser *p) {
   379→    Expr *left = parse_multiplicative(p);
   380→
   381→    while (parser_match(p, TOK_PLUS) || parser_match(p, TOK_MINUS)) {
   382→        const char *op = parser_match(p, TOK_PLUS) ? "+" : "-";
   383→        parser_advance(p);
   384→        Expr *right = parse_multiplicative(p);
   385→        left = expr_binary(left, right, op);
